class Printer {
  constructor(name) {
    this.name = name;
  }

  status() {
    return "ready";
  }
}

const office = new Printer("Office");

Printer.prototype.status = () => "busy";

let keys = "";
for (const key in office) keys += key;

console.log(office.status());
console.log(keys);
console.log(typeof Printer, typeof office);
console.log(Printer.prototype.constructor === office.constructor);
